<?php require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php';  $pageTitle='Teaching Assignments'; require_role(['admin']); require_once __DIR__.'/../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=$_POST['type'];if($type==='class'){$st=$pdo->prepare("INSERT IGNORE INTO teacher_classes(teacher_id,class_id) VALUES(?,?)");$st->execute([(int)$_POST['teacher_id'],(int)$_POST['class_id']]);}else{$st=$pdo->prepare("INSERT IGNORE INTO teacher_subjects(teacher_id,subject_id) VALUES(?,?)");$st->execute([(int)$_POST['teacher_id'],(int)$_POST['subject_id']]);}$saved=true;}
$teachers=$pdo->query("SELECT t.id,u.full_name,t.staff_no FROM teachers t JOIN users u ON u.id=t.user_id ORDER BY u.full_name")->fetchAll();$classes=$pdo->query("SELECT * FROM classes WHERE active=1 ORDER BY name")->fetchAll();$subjects=$pdo->query("SELECT * FROM subjects WHERE active=1 ORDER BY subject_name")->fetchAll();
?><h2>Teaching Assignments</h2><?php if(!empty($saved)): ?><div class="alert alert-success">Assignment saved.</div><?php endif;?><div class="row g-4"><div class="col-md-6"><div class="card p-4"><h5>Assign class</h5><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="type" value="class"><select class="form-select mb-3" name="teacher_id"><?php foreach($teachers as $t): ?><option value="<?=$t['id']?>"><?=e($t['full_name'].' — '.$t['staff_no'])?></option><?php endforeach;?></select><select class="form-select mb-3" name="class_id"><?php foreach($classes as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'].' '.$c['section'])?></option><?php endforeach;?></select><button class="btn btn-primary">Assign class</button></form></div></div><div class="col-md-6"><div class="card p-4"><h5>Assign subject</h5><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="type" value="subject"><select class="form-select mb-3" name="teacher_id"><?php foreach($teachers as $t): ?><option value="<?=$t['id']?>"><?=e($t['full_name'].' — '.$t['staff_no'])?></option><?php endforeach;?></select><select class="form-select mb-3" name="subject_id"><?php foreach($subjects as $s): ?><option value="<?=$s['id']?>"><?=e($s['subject_name'])?></option><?php endforeach;?></select><button class="btn btn-primary">Assign subject</button></form></div></div></div>
